public int climbStairsDistinctWays(int A) {
    final int MOD = 1000000007;
    if (A == 1 || A == 2) {
        return A;
    }

    long prev2 = 1; // f(1)
    long prev1 = 2; // f(2)

    for (int i = 3; i <= A; i++) {
        long curr = (prev1 + prev2) % MOD;
        prev2 = prev1;
        prev1 = curr;
    }

    return (int) prev1;
}

public int climbStairsDistinctWaysTopDown(int A) {
    int[] memory = new int[A + 1];
    Arrays.fill(memory, -1);
    return climbStairsMemo(A, memory);
}

private int climbStairsMemo(int A, int[] memory) {
    final int MOD = 1000000007;
    if (A == 1 || A == 2) {
        return A;
    }
    if (memory[A] != -1) {
        return memory[A];
    }
    memory[A] = (int) (((long) climbStairsMemo(A - 1, memory)
                      + (long) climbStairsMemo(A - 2, memory)) % MOD);
    return memory[A];
}

public int minimumNumberOfSquares(int A) {
    int[] memory = new int[A + 1];
    Arrays.fill(memory, -1);
    return minimumNumberOfSquares(A, memory);
}

private int minimumNumberOfSquares(int A, int[] memory) {
    if (A <= 0) {
        return 0;
    }
    if (memory[A] != -1) {
        return memory[A];
    }

    int minCount = Integer.MAX_VALUE;
    for (int i = 1; i * i <= A; i++) {
        int nextNum = A - (i * i);
        int result = minimumNumberOfSquares(nextNum, memory);
        minCount = Math.min(minCount, result + 1);
    }

    memory[A] = minCount; // memoise the state just solved, not the child
    return minCount;
}

