public int minimumNumberOfSquaresBottomUp(int A) {
    int[] dp = new int[A + 1];
    dp[0] = 0;

    for (int n = 1; n <= A; n++) {
        dp[n] = Integer.MAX_VALUE;
        for (int i = 1; i * i <= n; i++) {
            dp[n] = Math.min(dp[n], dp[n - (i * i)] + 1);
        }
    }

    return dp[A];
}

public int fibonacciNumber(int A) {
    int[] memory = new int[A + 1];
    Arrays.fill(memory, -1);
    return fibonacciNumber(A, memory);
}

private int fibonacciNumber(int A, int[] memory) {
    if (A == 0 || A == 1) {
        return A;
    }
    if (memory[A] != -1) {
        return memory[A];
    }

    memory[A] = fibonacciNumber(A - 1, memory) + fibonacciNumber(A - 2, memory);
    return memory[A];
}

public int fibonacciNumberBottomUp(int A) {
    if (A <= 1) {
        return A;
    }

    int prev2 = 0;
    int prev1 = 1;

    for (int i = 2; i <= A; i++) {
        int curr = prev1 + prev2;
        prev2 = prev1;
        prev1 = curr;
    }

    return prev1;
}

public int maxProductSubarray(final int[] A) {
    long maxEnd = A[0];
    long minEnd = A[0];
    long answer = A[0];

    for (int i = 1; i < A.length; i++) {
        long prevMax = maxEnd; // snapshot BEFORE overwriting, minEnd needs the old value
        long byMax = prevMax * A[i];
        long byMin = minEnd * A[i];

        maxEnd = Math.max(A[i], Math.max(byMax, byMin));
        minEnd = Math.min(A[i], Math.min(byMax, byMin));

        answer = Math.max(answer, maxEnd);
    }

    return (int) answer;
}

public int maximumSumValue(int[] A, int B, int C, int D) {
    int n = A.length;
    long[] prefixMax = new long[n];
    long[] suffixMax = new long[n];

    prefixMax[0] = (long) A[0] * B;
    for (int j = 1; j < n; j++) {
        prefixMax[j] = Math.max(prefixMax[j - 1], (long) A[j] * B);
    }

    suffixMax[n - 1] = (long) A[n - 1] * D;
    for (int j = n - 2; j >= 0; j--) {
        suffixMax[j] = Math.max(suffixMax[j + 1], (long) A[j] * D);
    }

    long answer = Long.MIN_VALUE;
    for (int j = 0; j < n; j++) {
        // prefixMax and suffixMax both include j, so i == j == k is allowed
        long curr = prefixMax[j] + (long) A[j] * C + suffixMax[j];
        answer = Math.max(answer, curr);
    }

    return (int) answer;
}

public int uniquePathsWithObstaclesInGrid(int[][] A) {
    int n = A.length;
    int m = A[0].length;
    if (A[0][0] == 1 || A[n - 1][m - 1] == 1) {
        return 0;
    }

    int[][] dp = new int[n][m];
    dp[0][0] = 1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (A[i][j] == 1) {
                dp[i][j] = 0;
                continue;
            }
            if (i == 0 && j == 0) {
                continue;
            }
            int top = (i > 0) ? dp[i - 1][j] : 0;
            int left = (j > 0) ? dp[i][j - 1] : 0;
            dp[i][j] = top + left;
        }
    }
    return dp[n - 1][m - 1];
}

public int numUniqueBSTrees(int A) {
    int[] memory = new int[A + 1];
    Arrays.fill(memory, -1);
    return numUniqueBSTrees(A, memory);
}

private int numUniqueBSTrees(int A, int[] memory) {
    if (A == 0 || A == 1) {
        return 1;
    }
    if (memory[A] != -1) {
        return memory[A];
    }

    int count = 0;
    for (int i = 0; i < A; i++) {
        count += numUniqueBSTrees(i, memory) * numUniqueBSTrees(A - (i + 1), memory);
    }
    memory[A] = count;
    return memory[A];
}

public int maxSumWithoutAdjacentElements(int[][] A) {
    int[] memory = new int[A[0].length];
    Arrays.fill(memory, -1);
    return maxSum(A, A[0].length - 1, memory);
}

private int maxSum(int[][] A, int col, int[] memory) {
    if (col < 0) {
        return 0;
    }
    if (col == 0) {
        return Math.max(A[0][0], A[1][0]);
    }
    if (memory[col] != -1) {
        return memory[col];
    }

    int pickTop = A[0][col] + maxSum(A, col - 2, memory);
    int pickBottom = A[1][col] + maxSum(A, col - 2, memory);
    int skip = maxSum(A, col - 1, memory);

    memory[col] = Math.max(Math.max(pickTop, pickBottom), skip);
    return memory[col];
}

private static final int MOD = 1000000007;

public int nDigitNumbersWithDigitSum(int A, int B) {
    int[][] memory = new int[A + 1][B + 1];
    for (int i = 0; i <= A; i++) {
        for (int j = 0; j <= B; j++) {
            memory[i][j] = -1;
        }
    }
    return nDigitNumbers(A, B, memory);
}

private int nDigitNumbers(int pos, int sum, int[][] memory) {
    if (pos == 1) {
        if (sum >= 1 && sum <= 9) {   // leading digit: 1-9 only
            return 1;
        } else {
            return 0;
        }
    }
    if (sum <= 0) {
        return 0;
    }
    if (memory[pos][sum] != -1) {
        return memory[pos][sum];
    }

    int count = 0;
    for (int i = 0; i <= 9; i++) {
        if (sum >= i) {
            count = (count + nDigitNumbers(pos - 1, sum - i, memory)) % MOD;
        }
    }
    memory[pos][sum] = count;
    return memory[pos][sum];
}

public int maximalRectangleInBinaryMatrix(int[][] A) {
    int n = A.length;
    int m = A[0].length;
    int[] heights = new int[m];
    int max = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (A[i][j] == 1) {
                heights[j] = heights[j] + 1;
            } else {
                heights[j] = 0;   // a zero breaks the column run, reset — never decrement
            }
        }
        max = Math.max(max, largestRectangleInHistogram(heights));
    }
    return max;
}

private int largestRectangleInHistogram(int[] heights) {
    int m = heights.length;
    Stack<Integer> stack = new Stack<>();
    int best = 0;

    for (int i = 0; i <= m; i++) {
        int curr = (i == m) ? 0 : heights[i];   // virtual zero bar flushes the stack
        while (!stack.isEmpty() && heights[stack.peek()] >= curr) {
            int height = heights[stack.pop()];
            int left = stack.isEmpty() ? -1 : stack.peek();
            best = Math.max(best, height * (i - left - 1));
        }
        stack.push(i);
    }
    return best;
}

public int minSumPathInMatrix(int[][] A) {
    int n = A.length;
    int m = A[0].length;
    int[] dp = new int[m];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (i == 0 && j == 0) {
                dp[j] = A[0][0];
            } else if (i == 0) {
                dp[j] = dp[j - 1] + A[i][j];
            } else if (j == 0) {
                dp[j] = dp[j] + A[i][j];   // dp[j] still holds the row above
            } else {
                dp[j] = Math.min(dp[j], dp[j - 1]) + A[i][j];
            }
        }
    }
    return dp[m - 1];
}

public int minimumSumPathInTriangle(int[][] A) {
    int n = A.length;
    int[] dp = new int[n];

    for (int j = 0; j < A[n - 1].length; j++) {
        dp[j] = A[n - 1][j];
    }

    for (int i = n - 2; i >= 0; i--) {
        for (int j = 0; j <= i; j++) {   // row i has exactly i+1 cells
            dp[j] = A[i][j] + Math.min(dp[j], dp[j + 1]);
        }
    }
    return dp[0];
}

public int intersectingChordsInCircle(int A) {
    final long MOD = 1000000007L;
    long[] dp = new long[A + 1];
    dp[0] = 1;

    for (int i = 1; i <= A; i++) {
        long count = 0;
        for (int j = 0; j < i; j++) {
            // long product: two values near MOD multiply to ~10^18, overflows int instantly
            count = (count + dp[j] * dp[i - j - 1]) % MOD;
        }
        dp[i] = count;
    }
    return (int) dp[A];
}

public int maxValueForKnapsack(int[] A, int[] B, int C) {
    int[][] memory = new int[A.length + 1][C + 1];
    for (int i = 0; i <= A.length; i++) {
        for (int j = 0; j <= C; j++) {
            memory[i][j] = -1;
        }
    }
    return maxValueForKnapsack(A, B, C, A.length - 1, memory);
}

private int maxValueForKnapsack(int[] values, int[] weights, int capacity, int index, int[][] memory) {
    if (index == 0) {
        if (weights[0] <= capacity) {
            return values[0];
        } else {
            return 0;
        }
    }
    if (memory[index][capacity] != -1) {
        return memory[index][capacity];
    }

    int ans = Integer.MIN_VALUE;
    if (capacity >= weights[index]) {
        ans = values[index] + maxValueForKnapsack(values, weights, capacity - weights[index], index - 1, memory);
    }
    ans = Math.max(ans, maxValueForKnapsack(values, weights, capacity, index - 1, memory));

    memory[index][capacity] = ans;
    return memory[index][capacity];
}

public int unboundedKnapsack(int A, int[] B, int[] C) {
    int[][] memory = new int[B.length + 1][A + 1];
    for (int i = 0; i <= B.length; i++) {
        for (int j = 0; j <= A; j++) {
            memory[i][j] = -1;
        }
    }
    return unboundedKnapsack(A, B.length - 1, B, C, memory);
}

private int unboundedKnapsack(int capacity, int index, int[] values, int[] weights, int[][] memory) {
    if (index == 0) {
        // unbounded: item 0 may be repeated, so take every copy that fits
        return (capacity / weights[0]) * values[0];
    }
    if (memory[index][capacity] != -1) {
        return memory[index][capacity];
    }

    // Option 1 : Not Select
    int ans = unboundedKnapsack(capacity, index - 1, values, weights, memory);
    // Option 2 : Select -> stay on the same index, the item is still available
    if (capacity >= weights[index]) {
        ans = Math.max(ans, values[index] + unboundedKnapsack(capacity - weights[index], index, values, weights, memory));
    }

    memory[index][capacity] = ans;
    return memory[index][capacity];
}

public int fractionalKnapsackMaxValue(int[] A, int[] B, int C) {
    int N = A.length;
    List<double[]> items = new ArrayList<>();

    for (int i = 0; i < N; i++) {
        items.add(new double[]{(double) A[i], (double) B[i], (double) A[i] / B[i]});
    }

    Collections.sort(items, new Comparator<double[]>() {
        @Override
        public int compare(double[] item1, double[] item2) {
            if (item2[2] > item1[2]) {
                return 1;
            } else if (item2[2] < item1[2]) {
                return -1;
            } else {
                return 0;
            }
        }
    });

    double totalValue = 0.0;
    double remainingCapacity = (double) C;

    for (double[] item : items) {
        if (remainingCapacity <= 0) {
            break;
        }

        double itemValue = item[0];
        double itemWeight = item[1];

        if (itemWeight <= remainingCapacity) {
            totalValue += itemValue;
            remainingCapacity -= itemWeight;
        } else {
            double fraction = remainingCapacity / itemWeight;
            totalValue += (fraction * itemValue);
            remainingCapacity = 0;
        }
    }

    double epsilon = 1e-9; // counter binary rounding before flooring
    return (int) Math.floor(totalValue * 100 + epsilon);
}

public int tusharsBirthdayPartyMinCost(int[] A, int[] B, int[] C) {
    int maxCapacity = 0;
    for (int capacity : A) {
        if (capacity > maxCapacity) {
            maxCapacity = capacity;
        }
    }

    int inf = Integer.MAX_VALUE / 2; // /2 so inf + cost never overflows
    int[] minCost = new int[maxCapacity + 1];
    for (int cap = 1; cap <= maxCapacity; cap++) {
        minCost[cap] = inf;
    }
    minCost[0] = 0;

    for (int cap = 1; cap <= maxCapacity; cap++) {
        for (int i = 0; i < B.length; i++) {
            if (B[i] <= cap && minCost[cap - B[i]] + C[i] < minCost[cap]) {
                minCost[cap] = minCost[cap - B[i]] + C[i];
            }
        }
    }

    int total = 0;
    for (int capacity : A) {
        total += minCost[capacity];
    }
    return total;
}

public int waysToSendSignal(int A) {
    int MOD = 1000000007;
    if (A == 1) {
        return 2;
    }
    if (A == 2) {
        return 3;
    }

    long a = 2, b = 3, c = 0;

    for (int i = 3; i <= A; i++) {
        c = (a + b) % MOD;
        a = b;
        b = c;
    }

    return (int) c;
}

public int buyingCandiesMaxSweetness(int[] A, int[] B, int[] C, int D) {
    int[] best = new int[D + 1];

    for (int budget = 1; budget <= D; budget++) {
        best[budget] = best[budget - 1]; // leftover budget is allowed
        for (int i = 0; i < A.length; i++) {
            if (C[i] <= budget) {
                int sweetness = A[i] * B[i];
                if (best[budget - C[i]] + sweetness > best[budget]) {
                    best[budget] = best[budget - C[i]] + sweetness;
                }
            }
        }
    }

    return best[D];
}

public int coinSumInfiniteWays(int[] A, int B) {
    final int MOD = 1_000_007;
    int[] dp = new int[B + 1];
    dp[0] = 1;
    for (int c = 0; c < A.length; c++) {
        int coin = A[c];
        for (int sum = coin; sum <= B; sum++) {
            // ascending sweep → dp[sum - coin] already used this coin, giving infinite supply
            dp[sum] = (dp[sum] + dp[sum - coin]) % MOD;
        }
    }
    return dp[B];
}

public int coinSumInfiniteWaysMemo(int[] A, int B) {
    int[][] memory = new int[A.length][B + 1];
    for (int i = 0; i < A.length; i++) {
        for (int j = 0; j <= B; j++) {
            memory[i][j] = -1;  // 0 is a valid answer, so -1 must be the sentinel
        }
    }
    return coinSumInfiniteWaysMemo(A, B, 0, memory);
}

private int coinSumInfiniteWaysMemo(int[] coins, int remaining, int index, int[][] memory) {
    if (remaining == 0) {
        return 1;
    }
    if (remaining < 0 || index == coins.length) {
        return 0;
    }
    if (memory[index][remaining] != -1) {
        return memory[index][remaining];
    }

    int include = coinSumInfiniteWaysMemo(coins, remaining - coins[index], index, memory);
    int exclude = coinSumInfiniteWaysMemo(coins, remaining, index + 1, memory);

    memory[index][remaining] = (include + exclude) % 1_000_007;
    return memory[index][remaining];
}

public int maxProfitFromRodCutting(int[] A) {
    int[] memory = new int[A.length];
    for (int i = 0; i < memory.length; i++) {
        memory[i] = -1;  // 0 is a valid profit, so -1 is the only safe sentinel
    }
    return maxProfitFromRodCutting(A, A.length, memory);
}

private int maxProfitFromRodCutting(int[] A, int index, int[] memory) {
    if (index == 0) {
        return 0;
    }
    if (memory[index - 1] != -1) {
        return memory[index - 1];
    }

    int maxProfit = 0;
    for (int i = 1; i <= index; i++) {
        int currentProfit = A[i - 1] + maxProfitFromRodCutting(A, index - i, memory);
        maxProfit = Math.max(maxProfit, currentProfit);
    }

    memory[index - 1] = maxProfit;
    return memory[index - 1];
}

public int knapsackTwoMaxValue(int[] A, int[] B, int C) {
    int n = A.length;
    int[] dp = new int[C + 1];

    for (int i = 0; i < n; i++) {
        for (int w = C; w >= B[i]; w--) {
            // descend so dp[w - B[i]] is still the row BEFORE item i (0/1, not unbounded)
            dp[w] = Math.max(dp[w], A[i] + dp[w - B[i]]);
        }
    }
    return dp[C];
}

