public int knapsackTwoMaxValueByValue(int[] A, int[] B, int C) {
    int n = A.length;
    int totalValue = 0;
    for (int i = 0; i < n; i++) {
        totalValue += A[i];
    }

    final long INF = Long.MAX_VALUE / 4;
    long[] dp = new long[totalValue + 1];
    for (int v = 1; v <= totalValue; v++) {
        dp[v] = INF;
    }
    dp[0] = 0;

    for (int i = 0; i < n; i++) {
        for (int v = totalValue; v >= A[i]; v--) {
            if (dp[v - A[i]] != INF) {  // guard: INF + weight would overflow
                dp[v] = Math.min(dp[v], dp[v - A[i]] + B[i]);
            }
        }
    }

    for (int v = totalValue; v >= 0; v--) {
        if (dp[v] <= C) {
            return v;
        }
    }
    return 0;
}

