public int numDistinctSubsequences(String A, String B) {
    final int MOD = 1_000_000_007;
    int n = A.length();
    int m = B.length();

    int[] dp = new int[m + 1];
    dp[0] = 1;  // empty prefix of B is formed exactly one way

    for (int i = 1; i <= n; i++) {
        for (int j = m; j >= 1; j--) {
            // descend so dp[j - 1] still holds the count for A's previous prefix
            if (A.charAt(i - 1) == B.charAt(j - 1)) {
                dp[j] = (dp[j] + dp[j - 1]) % MOD;
            }
        }
    }
    return dp[m];
}

public int letsPartyWays(int A) {
    final int MOD = 10003;
    long prev = 1;  // f(0)
    long curr = 1;  // f(1)

    for (int i = 2; i <= A; i++) {
        // cast to long BEFORE multiplying: (i-1) * prev exceeds int for large i
        long next = (curr + (long) (i - 1) * prev) % MOD;
        prev = curr;
        curr = next;
    }
    return (int) curr;
}

public int lengthOfLongestFibonacciSubsequence(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    int best = 0;

    for (int k = 2; k < n; k++) {
        for (int j = 1; j < k; j++) {
            int target = A[k] - A[j];
            if (target >= A[j]) {
                continue;  // strictly increasing ⇒ the earlier term must be < A[j]
            }
            int i = indexOfValue(A, target, j - 1);
            if (i < 0) {
                continue;
            }
            dp[j][k] = (dp[i][j] == 0) ? 3 : dp[i][j] + 1;
            best = Math.max(best, dp[j][k]);
        }
    }
    return best;
}

private int indexOfValue(int[] A, int target, int high) {
    int low = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (A[mid] == target) {
            return mid;
        }
        if (A[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

public int numDecodings(String A) {
    final int MOD = 1000000007;
    int n = A.length();
    if (n == 0 || A.charAt(0) == '0') {
        return 0;
    }

    int prev2 = 1; // dp[0] - the empty prefix has exactly one decoding
    int prev1 = 1; // dp[1]

    for (int i = 2; i <= n; i++) {
        int curr = 0;
        if (A.charAt(i - 1) != '0') {
            curr = prev1;
        }
        int two = (A.charAt(i - 2) - '0') * 10 + (A.charAt(i - 1) - '0');
        if (two >= 10 && two <= 26) { // 10..26 rejects "06" style pairs
            curr = (curr + prev2) % MOD;
        }
        prev2 = prev1;
        prev1 = curr % MOD;
    }

    return prev1;
}

