public int flipArrayMinimumElements(int[] A) {
    int total = 0;
    for (int value : A) {
        total += value;
    }

    int half = total / 2;
    int[] dp = new int[half + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int value : A) {
        for (int s = half; s >= value; s--) { // downward keeps it 0/1
            if (dp[s - value] != Integer.MAX_VALUE) {
                dp[s] = Math.min(dp[s], dp[s - value] + 1);
            }
        }
    }

    for (int s = half; s >= 0; s--) {
        if (dp[s] != Integer.MAX_VALUE) {
            return dp[s];
        }
    }

    return 0;
}
